    name: "clear-after-submit-form-schema.jsx",
    text: "import ChangesetWebform from 'react-changeset-webforms';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'clearAfterSubmitForm',\n    clearFormAfterSubmit: true,\n    submitButtonText: 'Create account',\n    clearFormButton: true,\n    resetFormButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      fieldLabel: 'email',\n      defaultValue: 'test@email.com',\n    },\n  ],\n};\n\nfunction submit() {\n  return new Promise((resolve) => {\n    setTimeout(() => {\n      resolve();\n    }, 2000);\n  });\n}\n\nexport default function ClearAfterSubmitFormSchema() {\n  return <ChangesetWebform formSchema={formSchema} submitData={submit} />;\n}",
