    name: "clone-group-form.jsx",
    text: "import ChangesetWebform from 'react-changeset-webforms';\n\nexport const formSchema = {\n  formSettings: {\n    formName: 'addEmails',\n    submitButtonText: 'Submit',\n    clearFormAfterSubmit: true,\n  },\n  fields: [\n    {\n      fieldId: 'emails',\n      fieldLabel: 'User emails',\n      fieldType: 'clone-group',\n      minClones: 2,\n      maxClones: 4,\n      validationRules: [\n        {\n          validationMethod: 'validateLength',\n          arguments: {\n            description: 'emails',\n            message: 'Too many {description} (maximum is {max}).',\n            max: 4,\n          },\n        },\n      ],\n      cloneButtonText: 'Add email address',\n      cloneFieldSchema: {\n        fieldLabel: 'Email',\n        fieldType: 'input',\n        inputType: 'email',\n        hideLabel: true,\n        validatesOn: ['$inherited', 'insertWithValue'],\n        validationRules: [\n          {\n            validationMethod: 'validateFormat',\n            arguments: { type: 'email' },\n          },\n          {\n            validationMethod: 'validatePresence',\n            arguments: true,\n          },\n          {\n            validationMethod: 'uniqueClone',\n            arguments: {\n              description: 'email',\n            },\n          },\n        ],\n      },\n    },\n  ],\n};\n\nexport default function CloneGroupForm() {\n  return (\n    <ChangesetWebform\n      formSchema={formSchema}\n      data-test-id=\"clonable-field-basics\"\n    />\n  );\n}",
