    text: "import React from 'react';\nimport ChangesetWebform from 'react-changeset-webforms';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'formMethods5',\n    hideSubmitButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      inputType: 'email',\n      fieldLabel: 'Email',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n  ],\n};\n\nexport default function FormMethodsExampleFive() {\n  const [data, setData] = React.useState(null);\n\n  async function onFieldValueChange(_formField, changesetWebform) {\n    setData(await changesetWebform.getData());\n  }\n\n  return (\n    <>\n      <div className=\"border rounded p-2 mb-4 bg-light\">\n        <ul>\n          <li>Name: {data?.name}</li>\n          <li>Email: {data?.email}</li>\n        </ul>\n      </div>\n      <ChangesetWebform\n        formSchema={formSchema}\n        onFieldValueChange={onFieldValueChange}\n      />\n    </>\n  );\n}",
