    name: "form-methods-example-four.jsx",
    text: "import React from 'react';\nimport ChangesetWebform from 'react-changeset-webforms';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'formMethods4',\n    hideSubmitButton: true,\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      inputType: 'email',\n      fieldLabel: 'Email',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n  ],\n};\n\nexport default function FormMethodsExampleFour() {\n  const [nextStepEnabled, setNextStepEnabled] = React.useState(false);\n\n  function afterFieldValidation(_formField, changesetWebform) {\n    setNextStepEnabled(\n      !changesetWebform.hasValidationErrors &&\n        !changesetWebform.hasUnvalidatedFields,\n    );\n  }\n\n  return (\n    <>\n      <div className=\"border rounded p-2 mb-4 bg-light\">\n        <div className=\"mt-2\">\n          {nextStepEnabled ? (\n            <>\n              <button\n                data-test-id=\"next-step-enabled\"\n                className=\"btn btn-primary me-2\"\n                type=\"button\"\n              >\n                Go to next step\n              </button>\n              <div\n                className=\"alert alert-success mb-0\"\n                data-test-id=\"alert-success\"\n              >\n                All validating fields have successfully validated.\n              </div>\n            </>\n          ) : (\n            <>\n              <button\n                data-test-id=\"next-step-disabled\"\n                className=\"btn btn-gray me-2\"\n                type=\"button\"\n                disabled\n              >\n                Next step disabled\n              </button>\n              <div\n                className=\"alert alert-danger mb-0\"\n                data-test-id=\"alert-danger\"\n              >\n                One or more validating fields has either failed validation, or\n                not yet been validated.\n              </div>\n            </>\n          )}\n        </div>\n      </div>\n      <ChangesetWebform\n        formSchema={formSchema}\n        afterFieldValidation={afterFieldValidation}\n      />\n    </>\n  );\n}",
