    text: "import ChangesetWebform from 'react-changeset-webforms';\n\nconst formSchema = {\n  formSettings: {\n    formName: 'formMethods6',\n  },\n  fields: [\n    {\n      fieldId: 'name',\n      fieldType: 'input',\n      fieldLabel: 'Name',\n      defaultValue: 'Steve Holt',\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n      ],\n    },\n    {\n      fieldId: 'email',\n      fieldType: 'input',\n      inputType: 'email',\n      fieldLabel: 'Email',\n      defaultValue: 'taken@example.com',\n      validationEvents: ['$inherited', 'insertWithValue'],\n      validationRules: [\n        {\n          validationMethod: 'validatePresence',\n          arguments: {\n            presence: true,\n          },\n        },\n        {\n          validationMethod: 'validateFormat',\n          arguments: { type: 'email' },\n        },\n      ],\n    },\n  ],\n};\n\nfunction submitData(data, changesetWebform) {\n  if (data.email === 'taken@example.com') {\n    changesetWebform.pushErrors({\n      fieldId: 'email',\n      errors: ['This email address is already taken. Please use another one.'],\n    });\n  }\n}\n\nexport default function FormMethodsExampleSix() {\n  return <ChangesetWebform formSchema={formSchema} submitData={submitData} />;\n}",
